86	template <int Stages>
87	CUTLASS_DEVICE
88	cutlass::PipelineTmaAsync<Stages> make_load_pipeline(
89	    typename cutlass::PipelineTmaAsync<Stages>::SharedStorage& storage,
90	    uint32_t transaction_bytes,
91	    WarpRole warp_role,
92	    uint32_t num_producers,
93	    uint32_t num_consumers
94	) {
95	    using Pipeline = cutlass::PipelineTmaAsync<Stages>;
96	    typename Pipeline::Params params;
97	
98	    auto role = Pipeline::ThreadCategory::NonParticipant;
99	    bool is_leader = false;
100	    if (warp_role == WarpRole::LOAD_QKG) {
101	        role = Pipeline::ThreadCategory::Producer;
102	        is_leader = cute::elect_one_sync();
103	    } else if (warp_role == WarpRole::MMA) {
104	        role = Pipeline::ThreadCategory::Consumer;
105	    }
106	
107	    params.transaction_bytes = transaction_bytes;
108	    params.role = role;
109	    params.is_leader = is_leader;
110	    params.num_consumers = num_consumers;
111	    params.num_producers = num_producers;
112	
113	    Pipeline pipeline(storage, params, Shape<_1,_1>{});
114	    cutlass::pipeline_init_wait(1);
115	    return pipeline;
116	}
